'use strict';

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var common = require( './common.js' );
var factory = require( './../lib/factory.js' );
var base = require( './../lib/base.js' );
var eligibility = require( './../lib/can_use_native.js' );
var native = tryRequire(resolve(__dirname, './../lib/native.js'));
var addon = tryRequire(resolve(__dirname, './../src/addon.node'));
var opts = {
	'skip': (native instanceof Error)
};
tape('main export is a function', opts, function test(t) {
	t.ok( true, __filename );
	t.strictEqual(typeof addon, 'function');
	t.strictEqual(require( './../lib' ), native, 'public native route');
	t.end();
});
tape('actual native panels preserve reference bits, guards and partial pivots', opts, function test(t) {
	common.corpus(t, native);
	common.diagonal(t, native);
	t.end();
});
tape('native eligibility bounds complete indexed sums and helper poststeps', function test(t) {
	var calls;
	var args;
	var fn;
	var k;
	var a;
	var w;
	var p;
	args = [
		121,
		2,
		2,
		null,
		0,
		null,
		1500000000,
		1000000000,
		0,
		null,
		1,
		0,
		null,
		1,
		2,
		0
	];
	t.strictEqual(eligibility(args), false, 'full A corner exceeds conservative native domain');
	args = [
		121,
		1,
		2,
		null,
		0,
		null,
		2147483640,
		1,
		0,
		null,
		1,
		0,
		null,
		1,
		1,
		0
	];
	t.strictEqual(eligibility(args), false, 'unused singleton stride still respects helper width domain');
	t.strictEqual(eligibility([
		121,
		0,
		2147483647,
		null,
		0
	]), false, 'wide valid empty NB uses JS');
	calls = 0;
	fn = factory(function dispatch() {
		if (eligibility(arguments)) {
			calls += 1;
		}
		return base.apply(null, arguments);
	});
	k = new Int32Array(1);
	a = new Float64Array([3]);
	p = new Int32Array(1);
	w = new Float64Array(2);
	t.strictEqual(fn.ndarray('lower', 1, 2, k, 0, a, 2147483647, 2147483647, 0, p, 1, 0, w, 2147483647, 1, 0), 0, 'wide valid JS singleton');
	t.strictEqual(calls, 0, 'safe explicit fallback');
	t.strictEqual(k[0], 1);
	t.strictEqual(p[0], 1);
	t.end();
});
tape('raw bridge rejects invalid metadata and overlapping tiny views before writes', opts, function test(t) {
	var slots;
	var args;
	var old;
	var a;
	var w;
	var k;
	var p;
	var i;
	a = new Float64Array([
		0,
		4,
		4,
		0
	]);
	w = new Float64Array(4);
	k = new Int32Array([99]);
	p = new Int32Array([
		12,
		13
	]);
	args = [
		122,
		2,
		2,
		k,
		0,
		a,
		1,
		2,
		0,
		p,
		1,
		0,
		w,
		1,
		2,
		0
	];
	slots = [
		1,
		2,
		4,
		6,
		7,
		8,
		10,
		11,
		13,
		14,
		15
	];
	for (i = 0; (i < slots.length); i++) {
		old = args[slots[i]];
		args[slots[i]] = 0.5;
		t.throws(function call() {
			addon.apply(null, args);
		}, RangeError, 'integral metadata');
		args[slots[i]] = old;
	}
	args[6] = 0;
	args[7] = 0;
	t.throws(function call() {
		addon.apply(null, args);
	}, RangeError, 'tiny broadcast matrix rejected before staging');
	args[6] = 1;
	args[7] = 2;
	args[12] = a;
	t.throws(function call() {
		addon.apply(null, args);
	}, RangeError, 'physical factor/scratch overlap');
	args[12] = w;
	t.deepEqual(a, new Float64Array([
		0,
		4,
		4,
		0
	]));
	t.deepEqual(k, new Int32Array([99]));
	t.deepEqual(p, new Int32Array([
		12,
		13
	]));
	t.deepEqual(w, new Float64Array(4));
	t.strictEqual(addon(121, 0, 2, k, 0, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined), 0, 'raw safe empty ignores inactive metadata');
	t.strictEqual(k[0], 0);
	t.end();
});
